installer-gui-script.script:
// Espalier is made to work with Grid. When Grid isn't there, say so, but let the
// installation go ahead: tabs work on their own too.
function checkGrid() {
    if (system.files.fileExistsAtPath('/Applications/Grid.app')) { return true; }
    my.result.type = 'Warning';
    my.result.title = 'Grid isn’t installed on this Mac';
    my.result.message = 'Espalier works alongside Grid, which snaps windows to halves (F5 and F6). '
        + 'Get Grid from its developer at macgrid.app, then run this installer again to give it '
        + 'the same shortcuts. You can continue without it.';
    return false;
}
